-- name: CreateCatalogConnection :one
-- The id is generated by the caller: credentials are sealed with the row id as
-- additional authenticated data, so it must be known before the insert.
INSERT INTO catalog_connections (id, name, type, url, config, credentials_enc, default_readonly, credentials_read_only, created_by)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
RETURNING *;

-- name: GetCatalogConnectionByID :one
SELECT * FROM catalog_connections WHERE id = $1;

-- name: ListCatalogConnections :many
SELECT * FROM catalog_connections WHERE created_by = $1 ORDER BY name;

-- name: ListVisibleCatalogConnections :many
-- The connections the caller may view: their own, and every one for an admin
-- (as authz.Connection and ListVisibleCatalogs), including the bootstrap
-- connection that has no owner.
SELECT * FROM catalog_connections
WHERE sqlc.arg(is_admin)::bool OR created_by = sqlc.arg(user_id)
ORDER BY name;

-- name: UpdateCatalogConnection :one
-- Partial update: only fields present in the request are written. COALESCE with
-- a NULL narg leaves omitted columns untouched, so concurrent PATCH requests to
-- different fields no longer overwrite each other.
UPDATE catalog_connections
SET name             = COALESCE(sqlc.narg('name'), name),
    url              = COALESCE(sqlc.narg('url'), url),
    config           = COALESCE(sqlc.narg('config'), config),
    credentials_enc  = COALESCE(sqlc.narg('credentials_enc'), credentials_enc),
    default_readonly = COALESCE(sqlc.narg('default_readonly'), default_readonly),
    credentials_read_only = COALESCE(sqlc.narg('credentials_read_only'), credentials_read_only),
    updated_at       = now()
WHERE id = sqlc.arg('id')
RETURNING *;

-- name: DeleteCatalogConnection :exec
DELETE FROM catalog_connections WHERE id = $1;
-- name: CatalogConnectionNameExists :one
SELECT EXISTS (SELECT 1 FROM catalog_connections WHERE name = $1);

-- name: CountEncryptedConnections :one
-- Whether any credential is stored, so a missing encryption key is fatal.
SELECT count(*) FROM catalog_connections WHERE credentials_enc IS NOT NULL;
